"use client";

import { CornerDownLeft, Search } from "lucide-react";
import { useCallback, useEffect, useId, useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { Kbd } from "@/components/ui/kbd";
import { cn } from "@/lib/utils";

/**
 * Komut paleti (⌘K / Ctrl+K). Yerel `<dialog>` üstünde bir combobox:
 * giriş alanı `role="combobox"`, liste `role="listbox"`, etkin satır
 * `aria-activedescendant` ile söylenir. Odak HEP girişte kalır; ok tuşları
 * odağı değil etkin satırı taşır, böylece yazmaya devam edilebilir.
 *
 * Diyalog yerel: odak tuzağı ve Escape tarayıcıdan, odak kapanınca açan
 * öğeye döner. Başlıktaki bir düğmeden açmak için `openCommandPalette()`.
 * Modal `<dialog>` arkadaki sayfanın kaymasını durdurmaz; sayaçlı kaydırma
 * kilidi `dialog.tsx` ile aynı, yalnızca başka katmanın tuttuğu kilide
 * dokunmaz. Dosya tek başına kopyalanabilsin diye burada da var; ikisi
 * birlikteyse kilidi tek modüle (`use-scroll-lock.ts`) taşı.
 *
 * Satırlar gruplanarak çizilir; ok tuşları da EKRANDAKİ sırayı izler, girdi
 * dizisinin sırasını değil (bir grubun komutları dağınık gelse bile).
 *
 * Komutlar veri: `onSelect` içinde ne yapılacağını çağıran bilir
 * (`router.push`, tema değişimi). Palet gezinmeyi kendisi yapmaz, bu yüzden
 * herhangi bir yönlendiriciye bağlı değil.
 *
 * GÖRÜNÜŞ ("board" dili, 2026-11): beyaz karo `rounded-2xl` + kıl çizgisi +
 * `shadow-modal`, giriş 0,96'dan ölçek + opaklık. Üstte arama, ortada
 * `p-1.5` liste; etkin satır yumuşak gri (`bg-surface-raised`), ikonu ve
 * kısayol hapları sağda (`kbd.tsx`). Altta "Gezin ↑ ↓ · Seç ↵ · Kapat Esc"
 * künyesi: klavyeyi bilmeyen kullanıcıya yolu söyler. Künye ve haplar
 * yalnızca hassas işaretçide (dokunmatikte klavye kısayolu anlamsız).
 *
 * Arama Türkçe küçük harfle karşılaştırır (`toLocaleLowerCase("tr-TR")`):
 * "İ" aranınca "i", "I" aranınca "ı" bulunur. `keywords` eş anlamlılar
 * içindir ("tema" → "görünüm").
 */

export type Command = {
  id: string;
  label: string;
  /** Satırın altında cümle düzeninde kısa açıklama. */
  hint?: string;
  /** Grup başlığı: "Gezinme", "Ayarlar". */
  group: string;
  icon?: ReactNode;
  /** Görsel ipucu: ["G", "H"]. Kısayolun kendisini ayrıca bağla. */
  shortcut?: readonly string[];
  keywords?: readonly string[];
  onSelect: () => void;
};

const OPEN_EVENT = "command-palette:open";

/** Paleti ağacın herhangi bir yerinden aç (başlıktaki arama düğmesi). */
export function openCommandPalette() {
  window.dispatchEvent(new Event(OPEN_EVENT));
}

const fold = (value: string) => value.toLocaleLowerCase("tr-TR");

let lockCount = 0;
// Palet genel kısayolla açık bir Dialog'un ÜSTÜNDE de açılır. Sayfa zaten
// kilitliyse kilit o katmanın: palet ona dokunmaz, kapanırken de sökmez;
// yoksa Dialog açık dururken arkadaki sayfa kaymaya başlardı.
let ownsLock = false;

function lockScroll() {
  lockCount += 1;
  if (lockCount === 1) {
    ownsLock = document.documentElement.style.overflow !== "hidden";
    if (!ownsLock) return;
    const gap = window.innerWidth - document.documentElement.clientWidth;
    document.documentElement.style.overflow = "hidden";
    // Kaydırma çubuğu kaybolunca sayfa yana kaymasın.
    if (gap > 0) document.documentElement.style.paddingRight = `${gap}px`;
  }
}

function unlockScroll() {
  lockCount = Math.max(0, lockCount - 1);
  if (lockCount === 0 && ownsLock) {
    document.documentElement.style.removeProperty("overflow");
    document.documentElement.style.removeProperty("padding-right");
  }
}

type CommandPaletteProps = {
  commands: readonly Command[];
  placeholder?: string;
  emptyText?: string;
  /** Diyaloğun ekran okuyucu adı. */
  label?: string;
};

export function CommandPalette({
  commands,
  placeholder = "Komut ya da sayfa ara",
  emptyText = "Eşleşen komut yok.",
  label = "Komut Paleti",
}: CommandPaletteProps) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const dialog = useRef<HTMLDialogElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const opener = useRef<HTMLElement | null>(null);
  const pressedBackdrop = useRef(false);
  const listId = useId();

  const results = useMemo(() => {
    const q = fold(query.trim());
    if (!q) return commands;
    return commands.filter((command) =>
      [command.label, command.hint ?? "", command.group, ...(command.keywords ?? [])].some((text) => fold(text).includes(q)),
    );
  }, [commands, query]);

  const groups = useMemo(() => {
    const map = new Map<string, Command[]>();
    for (const command of results) map.set(command.group, [...(map.get(command.group) ?? []), command]);
    return [...map.entries()];
  }, [results]);

  // Ekrandaki sıra; `active` bu dizinin indeksi.
  const ordered = useMemo(() => groups.flatMap(([, items]) => items), [groups]);

  const close = useCallback(() => {
    setOpen(false);
    setQuery("");
    setActive(0);
  }, []);

  useEffect(() => {
    const onKey = (event: globalThis.KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setOpen((value) => !value);
      }
    };
    const onOpen = () => setOpen(true);
    window.addEventListener("keydown", onKey);
    window.addEventListener(OPEN_EVENT, onOpen);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener(OPEN_EVENT, onOpen);
    };
  }, []);

  useEffect(() => {
    const node = dialog.current;
    if (!node || !open) return;
    opener.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    if (!node.open) node.showModal();
    input.current?.focus();
    lockScroll();
    return () => {
      node.close();
      unlockScroll();
      if (opener.current?.isConnected) opener.current.focus();
    };
  }, [open]);

  // Etkin satır görünür alanın dışına düşmesin.
  useEffect(() => {
    document.getElementById(`${listId}-${active}`)?.scrollIntoView({ block: "nearest" });
  }, [active, listId]);

  function run(command: Command | undefined) {
    if (!command) return;
    close();
    command.onSelect();
  }

  function onKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    const last = ordered.length - 1;
    if (event.key === "ArrowDown") {
      event.preventDefault();
      setActive((index) => (index >= last ? 0 : index + 1));
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setActive((index) => (index <= 0 ? last : index - 1));
    } else if (event.key === "Home" && event.ctrlKey) {
      setActive(0);
    } else if (event.key === "End" && event.ctrlKey) {
      setActive(last);
    } else if (event.key === "Enter") {
      event.preventDefault();
      run(ordered[active]);
    }
  }

  const activeId = results.length ? `${listId}-${active}` : undefined;

  return (
    <dialog
      ref={dialog}
      aria-label={label}
      onCancel={(event) => {
        event.preventDefault();
        close();
      }}
      onPointerDown={(event) => {
        // Arka plan yalnızca basış ORADA başladıysa kapatır: arama metnini
        // seçip dışarıda bırakmak da diyaloğun kendisine `click` düşürür.
        pressedBackdrop.current = event.target === event.currentTarget;
      }}
      onClick={(event) => {
        const backdrop = pressedBackdrop.current && event.target === event.currentTarget;
        pressedBackdrop.current = false;
        if (backdrop) close();
      }}
      className={cn(
        "mx-auto mt-[12dvh] w-[calc(100%-2rem)] max-w-xl overflow-hidden rounded-2xl border border-line bg-overlay p-0 text-body shadow-modal",
        "scale-[0.96] opacity-0 transition-[opacity,scale,display,overlay] transition-discrete duration-200 ease-[var(--ease-brand)] open:scale-100 open:opacity-100 starting:open:scale-[0.96] starting:open:opacity-0",
        "backdrop:bg-scrim backdrop:opacity-0 backdrop:transition-[opacity,display,overlay] backdrop:transition-discrete backdrop:duration-200 open:backdrop:opacity-100 starting:open:backdrop:opacity-0",
      )}
    >
      <div className="flex items-center gap-3 border-b border-line-soft px-4">
        <Search aria-hidden className="size-[1.125rem] shrink-0 text-muted" strokeWidth={1.75} />
        <input
          ref={input}
          role="combobox"
          aria-expanded="true"
          aria-controls={listId}
          aria-activedescendant={activeId}
          aria-autocomplete="list"
          aria-label={placeholder}
          value={query}
          onChange={(event) => {
            setQuery(event.target.value);
            setActive(0);
          }}
          onKeyDown={onKeyDown}
          placeholder={placeholder}
          autoComplete="off"
          spellCheck={false}
          className="min-h-14 min-w-0 flex-1 bg-transparent text-read text-strong outline-none placeholder:text-muted"
        />
        <Kbd aria-hidden className="hidden pointer-fine:inline-flex">
          Esc
        </Kbd>
      </div>

      {/* Boş metin listbox'ın DIŞINDA: listbox yalnız option/group çocuk alır
          (axe aria-required-children, Storybook ölçtü). role="status" duyurur. */}
      {results.length === 0 ? (
        <p role="status" className="px-3 py-8 text-center text-base text-muted">{emptyText}</p>
      ) : null}
      <div id={listId} role="listbox" aria-label={label} hidden={results.length === 0} className="max-h-[min(22rem,55dvh)] overflow-y-auto overscroll-contain p-1.5">
        {groups.map(([group, items]) => (
            <div key={group} role="group" aria-label={group}>
              <p aria-hidden className="px-2.5 pt-2.5 pb-1.5 text-micro font-medium text-muted">
                {group}
              </p>
              {items.map((command) => {
                const index = ordered.indexOf(command);
                const selected = index === active;
                return (
                  <div
                    key={command.id}
                    id={`${listId}-${index}`}
                    role="option"
                    aria-selected={selected}
                    onClick={() => run(command)}
                    onPointerMove={() => setActive(index)}
                    className={cn(
                      "flex min-h-11 cursor-pointer items-center gap-3 rounded-md px-2.5 py-2 transition-colors duration-100 [&_svg]:size-4 [&_svg]:shrink-0",
                      selected ? "bg-surface-raised text-strong" : "text-body",
                    )}
                  >
                    {command.icon ? (
                      <span
                        aria-hidden
                        className={cn(
                          "grid size-8 shrink-0 place-items-center rounded-sm border border-line bg-overlay shadow-raised transition-colors",
                          selected ? "text-strong" : "text-muted",
                        )}
                      >
                        {command.icon}
                      </span>
                    ) : null}
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-base font-medium">{command.label}</span>
                      {command.hint ? <span className="block truncate text-small text-muted">{command.hint}</span> : null}
                    </span>
                    {command.shortcut ? (
                      <span aria-hidden className="hidden gap-1 pointer-fine:flex">
                        {command.shortcut.map((key) => (
                          <Kbd key={key}>{key}</Kbd>
                        ))}
                      </span>
                    ) : selected ? (
                      <CornerDownLeft aria-hidden className="hidden text-muted pointer-fine:block" strokeWidth={1.75} />
                    ) : null}
                  </div>
                );
              })}
            </div>
          ))}
      </div>

      <p aria-hidden className="hidden items-center gap-4 border-t border-line-soft bg-surface px-4 py-2.5 text-small text-muted pointer-fine:flex">
        <span className="inline-flex items-center gap-1.5">
          Gezin <Kbd>↑</Kbd>
          <Kbd>↓</Kbd>
        </span>
        <span className="inline-flex items-center gap-1.5">
          Seç <Kbd>↵</Kbd>
        </span>
        <span className="ml-auto inline-flex items-center gap-1.5">
          Kapat <Kbd>Esc</Kbd>
        </span>
      </p>
    </dialog>
  );
}
